import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useSelector } from 'react-redux';
import Header from '../../components/ui/Header';
import Footer from '../../components/ui/Footer';
import Icon from '../../components/AppIcon';
import Button from '../../components/ui/Button';

const AcademyCommons = () => {
    const navigate = useNavigate();
    const { user } = useSelector((state) => state.auth);

    // KEYHOLDER LOGIC: Define who can start sessions
    const canLaunchWeekly = ['admin', 'ambassador', 'founder', 'contributor'].includes(user?.role?.toLowerCase());
    const canLaunchMonthly = ['admin', 'instructor', 'founder'].includes(user?.role?.toLowerCase());

    // TIME-GATE LOGIC: Determine if it's currently the weekend or month-end
    const now = new Date();
    const day = now.getDay(); // 0=Sun, 5=Fri, 6=Sat
    const isWeekend = [0, 5, 6].includes(day);

    // Month-end check: Last Friday, Saturday, or Sunday of the month
    const nextWeek = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000);
    const isMonthEnd = isWeekend && nextWeek.getMonth() !== now.getMonth();

    const isLive = (type) => {
        if (type === 'weekly') return isWeekend;
        if (type === 'monthly') return isMonthEnd;
        return false;
    };

    const events = [
        {
            id: 1,
            type: 'weekly',
            title: 'Weekend Scholars Pulse',
            description: 'Casual networking, squad brainstorming, and peer-to-peer knowledge sharing.',
            time: 'Every Saturday, 4:00 PM GMT',
            icon: 'Users',
            color: 'from-emerald-500 to-teal-600',
            status: 'upcoming',
            canLaunch: canLaunchWeekly
        },
        {
            id: 2,
            type: 'monthly',
            title: 'The Monthly Summit',
            description: 'Exclusive Q&A and strategy session with Senior Instructors and Industry Experts.',
            time: 'Last Friday of the Month, 6:00 PM GMT',
            icon: 'Crown',
            color: 'from-amber-500 to-orange-600',
            status: 'premium',
            canLaunch: canLaunchMonthly
        }
    ];

    return (
        <div className="min-h-screen bg-slate-950 flex flex-col selection:bg-primary/30">
            <Header />

            <main className="flex-1">
                {/* Cinematic Hero */}
                <section className="relative pt-32 pb-20 overflow-hidden border-b border-white/5">
                    <div className="absolute inset-0 z-0">
                        <div className="absolute top-0 left-1/2 -translate-x-1/2 w-[1000px] h-[600px] bg-primary/10 rounded-full blur-[120px] -mt-48" />
                    </div>

                    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative z-10 text-center">
                        <div className="flex justify-start mb-8">
                            <button 
                                onClick={() => navigate('/academy')}
                                className="flex items-center gap-2 text-slate-500 hover:text-white transition-colors group"
                            >
                                <Icon name="ArrowLeft" size={18} className="group-hover:-translate-x-1 transition-transform" />
                                <span className="text-sm font-bold uppercase tracking-widest">Back to Academy</span>
                            </button>
                        </div>
                        <div className="inline-flex items-center gap-2 px-3 py-1 bg-primary/10 border border-primary/20 rounded-lg mb-8">
                            <Icon name="MessageSquare" size={14} className="text-primary" />
                            <span className="text-[10px] font-black uppercase tracking-widest text-primary">The Global Campus Hub</span>
                        </div>
                        <h1 className="text-5xl md:text-8xl font-black text-white italic tracking-tighter leading-[0.85] mb-8">
                            THE <br />
                            <span className="text-primary">COMMONS.</span>
                        </h1>
                        <p className="text-lg md:text-xl text-slate-400 font-medium max-w-2xl mx-auto leading-relaxed">
                            Where the global tribe meets. From casual weekend pulses to high-prestige monthly summits with industry legends.
                        </p>
                    </div>
                </section>

                {/* Event Schedule */}
                <section className="py-24">
                    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                        <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
                            {events.map((event) => (
                                <div key={event.id} className="group relative">
                                    <div className="absolute -inset-1 bg-gradient-to-r from-white/5 to-white/0 rounded-[3rem] blur-xl opacity-0 group-hover:opacity-100 transition-opacity duration-700" />
                                    
                                    <div className="relative bg-white/[0.03] border border-white/10 rounded-[3rem] p-8 md:p-12 overflow-hidden h-full flex flex-col">
                                        <div className={`absolute top-0 right-0 w-32 h-32 bg-gradient-to-br ${event.color} opacity-10 blur-3xl -mr-16 -mt-16 group-hover:opacity-20 transition-opacity`} />
                                        
                                        <div className="flex items-start justify-between mb-10">
                                            <div className={`w-16 h-16 bg-gradient-to-br ${event.color} rounded-2xl flex items-center justify-center shadow-2xl`}>
                                                <Icon name={event.icon} size={32} className="text-white" />
                                            </div>
                                            <div className="px-4 py-1.5 bg-white/5 rounded-full border border-white/10 text-[10px] font-black uppercase tracking-widest text-slate-400">
                                                {event.type}
                                            </div>
                                        </div>

                                        <h3 className="text-3xl md:text-4xl font-black text-white italic mb-4 tracking-tighter group-hover:text-primary transition-colors">
                                            {event.title}
                                        </h3>
                                        <p className="text-slate-400 font-medium leading-relaxed mb-8 flex-1">
                                            {event.description}
                                        </p>

                                        <div className="space-y-6 pt-8 border-t border-white/5">
                                            <div className="flex items-center gap-4 text-white font-bold">
                                                <Icon name="Calendar" size={20} className="text-primary" />
                                                <span className="text-sm md:text-base">{event.time}</span>
                                            </div>
                                            <Button 
                                                disabled={!isLive(event.type) && !canLaunchWeekly} // Admins can always bypass for testing
                                                className={`w-full py-6 font-black italic shadow-xl ${event.canLaunch ? 'bg-primary text-white hover:bg-secondary' : 'bg-white text-slate-950 hover:bg-slate-200'} ${!isLive(event.type) && !canLaunchWeekly ? 'opacity-50 grayscale cursor-not-allowed' : ''}`}
                                                onClick={() => navigate('/academy/live/hangout-room')}
                                                iconName={!isLive(event.type) && !canLaunchWeekly ? 'Lock' : (event.canLaunch ? 'Zap' : 'Users')}
                                            >
                                                {!isLive(event.type) && !canLaunchWeekly 
                                                    ? `LOCKED UNTIL ${event.type === 'weekly' ? 'FRIDAY' : 'MONTH-END'}` 
                                                    : (event.canLaunch ? 'LAUNCH GLOBAL SESSION' : 'JOIN HANGOUT ROOM')
                                                }
                                            </Button>
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                </section>

                {/* Campus Culture Section */}
                <section className="py-24 bg-white/[0.02] border-y border-white/5">
                    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 text-center">
                        <h2 className="text-4xl font-black text-white italic mb-16 tracking-tighter uppercase">Campus Traditions</h2>
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-12">
                            <div className="space-y-4">
                                <div className="text-primary mb-6 flex justify-center">
                                    <Icon name="Coffee" size={48} />
                                </div>
                                <h4 className="text-xl font-black text-white italic uppercase tracking-tighter">Idea Exchange</h4>
                                <p className="text-slate-500 text-sm font-medium">Unfiltered sessions where founders pitch their early-stage concepts to peers for brutal, honest feedback.</p>
                            </div>
                            <div className="space-y-4">
                                <div className="text-primary mb-6 flex justify-center">
                                    <Icon name="Zap" size={48} />
                                </div>
                                <h4 className="text-xl font-black text-white italic uppercase tracking-tighter">Skill Sprints</h4>
                                <p className="text-slate-500 text-sm font-medium">Flash sessions during hangouts where experts teach one "Quick Win" skill in under 10 minutes.</p>
                            </div>
                            <div className="space-y-4">
                                <div className="text-primary mb-6 flex justify-center">
                                    <Icon name="ShieldCheck" size={48} />
                                </div>
                                <h4 className="text-xl font-black text-white italic uppercase tracking-tighter">Integrity Circles</h4>
                                <p className="text-slate-500 text-sm font-medium">Small, high-trust breakouts to discuss the ethics and impact of our global projects.</p>
                            </div>
                        </div>
                    </div>
                </section>

                {/* Global Call to Action */}
                <section className="py-24 text-center">
                    <div className="max-w-4xl mx-auto px-4">
                        <h2 className="text-4xl font-black text-white italic mb-8 tracking-tighter uppercase">Don't Build Alone.</h2>
                        <p className="text-slate-500 text-lg mb-12 font-medium">
                            The Commons is always open for those who want to build a legacy with a global tribe.
                        </p>
                        <Button 
                            size="xl" 
                            variant="outline" 
                            className="border-white/10 text-white hover:bg-white/5 font-black italic px-16"
                        >
                            ADD TO MY CALENDAR
                        </Button>
                    </div>
                </section>
            </main>

            <Footer />
        </div>
    );
};

export default AcademyCommons;
